import { FilterDataStructure, FilterValue } from 'models/Filters';

import { FilterConfig } from '../types';

const getSkuFilterData = (filterData: FilterDataStructure) => filterData.sku;

const flatListCalculator =
  (key: string) => (filterData: FilterDataStructure) => {
    const block = (filterData as Record<string, unknown>)[key] as
      | {
          default?: { value?: FilterValue };
          values?: { value?: FilterValue }[];
        }
      | undefined;
    return block?.default?.value ?? block?.values?.[0]?.value ?? null;
  };

const flatListValidator =
  (key: string) => (filterData: FilterDataStructure, value: FilterValue) => {
    if (value == null || value === '') return true;
    const block = (filterData as Record<string, unknown>)[key] as
      | { values?: { value?: FilterValue }[] }
      | undefined;
    const list = block?.values;
    if (!list?.length) return false;
    return list.some((opt) => opt.value === value);
  };

export const categoryFilterConfig: FilterConfig = {
  key: 'category',
  order: 54,
  isCommon: false,
  calculator: flatListCalculator('category'),
  validator: flatListValidator('category'),
  metadata: {
    displayName: 'Category',
    description: 'Commercial Results — category (flat preset)',
  },
};

export const nonAlcoholicFilterConfig: FilterConfig = {
  key: 'non_alcoholic',
  order: 55,
  isCommon: false,
  calculator: flatListCalculator('non_alcoholic'),
  validator: flatListValidator('non_alcoholic'),
  metadata: {
    displayName: 'Non-Alc Beer',
    description: 'Commercial Results — non-alcoholic beer type',
  },
};

export const packTypeFilterConfig: FilterConfig = {
  key: 'pack_type',
  order: 56,
  isCommon: false,
  calculator: flatListCalculator('pack_type'),
  validator: flatListValidator('pack_type'),
  metadata: {
    displayName: 'Pack Type',
    description: 'Commercial Results — pack type',
  },
};

export const channelFilterConfig: FilterConfig = {
  key: 'channel',
  order: 57,
  isCommon: false,
  calculator: flatListCalculator('channel'),
  validator: flatListValidator('channel'),
  metadata: {
    displayName: 'Channel',
    description: 'Commercial Results — channel',
  },
};

export const skuCommercialFilterConfig: FilterConfig = {
  key: 'sku',
  order: 52,
  isCommon: false,
  parentKey: 'brands',
  calculator: (filterData, defaults) => {
    const brand = defaults.brands;
    if (!brand || brand === 'All') return null;
    const byBrand = getSkuFilterData(filterData)?.values?.[String(brand)];
    if (!byBrand?.length) return null;
    return byBrand[0]?.value ?? null;
  },
  dependentDefaultCascadingCalculator: (filterData, currentValues) => {
    const brand = currentValues.brands;
    if (!brand || brand === 'All') return null;
    const list = getSkuFilterData(filterData)?.values?.[String(brand)];
    if (!list?.length) return null;
    const cur = currentValues.sku;
    if (cur != null && list.some((o) => o.value === cur)) return cur;
    return list[0]?.value ?? null;
  },
  validator: (filterData, value) => {
    if (value == null || value === '') return true;
    const valuesByBrand = getSkuFilterData(filterData)?.values;
    if (!valuesByBrand) return false;
    return Object.values(valuesByBrand)
      .flat()
      .some((o) => o.value === value);
  },
  metadata: {
    displayName: 'SKU',
    description: 'Commercial Results — SKU list scoped by brand',
  },
};
